sed -i '/SettingsChoiceRow(/,/onValueChange = { prefs.theme = it; refresh++ }/!b;//!d;/SettingsChoiceRow(/!d;s/.*onValueChange = { prefs.theme = it; refresh++ }.*/                    SettingsChoiceRow(\n                        title = stringResource(R.string.theme),\n                        icon = Icons.Default.Palette,\n                        entries = stringArrayResource(R.array.theme_entries).toList(),\n                        values = stringArrayResource(R.array.theme_values).toList(),\n                        currentValue = prefs.theme,\n                        onValueChange = { selected ->\n                            originalTheme = prefs.theme\n                            prefs.theme = selected\n                            previewTheme = selected\n                            refresh++\n                        }\n                    )/' app/src/main/java/org/slashboard/ime/settings/SettingsActivity.kt
